CREATE TABLE IF NOT EXISTS ward_evidence_match_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artifact_id uuid NOT NULL REFERENCES ward_evidence_artifacts(id) ON DELETE CASCADE, exception_id uuid NOT NULL, match_type text NOT NULL, confidence_score numeric(5,2) NOT NULL, evidence_notes text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(artifact_id,exception_id));